using System.Collections.Immutable;using System.Globalization;
namespace DeliveryApp;
public static class DeliveryPipeline{
 public const decimal MaximumDistance=20m;
 public static DeliveryWorkflowState Start(ImmutableArray<ValidatedDeliveryRequest> requests)=>new DeliveryWorkflowState.Ready(requests);
 public static DeliveryWorkflowState Complete(DeliveryWorkflowState state,Func<decimal,decimal> pricingPolicy)=>state switch{DeliveryWorkflowState.Ready r=>new DeliveryWorkflowState.Completed(ExecuteValidated(r.Requests,pricingPolicy)),DeliveryWorkflowState.Completed=>new DeliveryWorkflowState.Failed("Workflow has already been completed."),DeliveryWorkflowState.Failed f=>new DeliveryWorkflowState.Failed($"Workflow cannot continue: {f.Reason}"),_=>new DeliveryWorkflowState.Failed("Unknown state.")};
 public static DeliverySummary ExecuteValidated(ImmutableArray<ValidatedDeliveryRequest> requests,Func<decimal,decimal> pricingPolicy){ArgumentNullException.ThrowIfNull(pricingPolicy);var eligible=requests.Where(x=>x.DistanceKm<=MaximumDistance).ToArray();var quotes=eligible.Select(x=>{var z=NativeZoneAdapter.GetZone(x.DistanceKm);if(z is Result<int,DomainError>.Err e)throw new InvalidOperationException(e.Error.ToString());return new DeliveryQuote(x.Id,x.DistanceKm,pricingPolicy(x.DistanceKm),((Result<int,DomainError>.Ok)z).Value);}).OrderBy(x=>x.Cost).ThenBy(x=>x.Id,StringComparer.Ordinal).ToImmutableArray();return new(quotes,quotes.Length,requests.Length-quotes.Length,quotes.Sum(x=>x.Cost));}
 public static Maybe<ValidatedDeliveryRequest> FindById(ImmutableArray<ValidatedDeliveryRequest> items,string id){var x=items.FirstOrDefault(x=>string.Equals(x.Id,id,StringComparison.OrdinalIgnoreCase));return x is null?new Maybe<ValidatedDeliveryRequest>.None():new Maybe<ValidatedDeliveryRequest>.Some(x);}
 public static Result<DeliveryQuote,DomainError> QuoteById(ImmutableArray<ValidatedDeliveryRequest> items,string id,Func<decimal,decimal> policy){var found=FindById(items,id);if(found is Maybe<ValidatedDeliveryRequest>.None)return new Result<DeliveryQuote,DomainError>.Err(new("DELIVERY_NOT_FOUND",$"Delivery '{id}' was not found."));var r=((Maybe<ValidatedDeliveryRequest>.Some)found).Value;if(r.DistanceKm>MaximumDistance)return new Result<DeliveryQuote,DomainError>.Err(new("DISTANCE_LIMIT","Delivery exceeds 20 km."));var z=NativeZoneAdapter.GetZone(r.DistanceKm);if(z is Result<int,DomainError>.Err e)return new Result<DeliveryQuote,DomainError>.Err(e.Error);return new Result<DeliveryQuote,DomainError>.Ok(new(r.Id,r.DistanceKm,policy(r.DistanceKm),((Result<int,DomainError>.Ok)z).Value));}
 public static Result<QuoteDisplay,DomainError> CreateQuoteDisplay(ImmutableArray<ValidatedDeliveryRequest> items,string id,Func<decimal,decimal> policy)=>new Result<string,DomainError>.Ok(id).Bind(x=>QuoteById(items,x,policy)).Map(q=>new QuoteDisplay(q.Id,$"{q.DistanceKm.ToString("0.##",CultureInfo.InvariantCulture)} km",q.Cost.ToKzt()));
 public static IEnumerable<ValidatedDeliveryRequest> StreamEligible(IEnumerable<ValidatedDeliveryRequest> items,Action? onYield=null){foreach(var item in items){if(item.DistanceKm<=MaximumDistance){onYield?.Invoke();yield return item;}}}
 public static DeliveryReportRow[] DetailedReport(IEnumerable<ValidatedDeliveryRequest> items,Func<decimal,decimal> score){return items.WithinServiceRange(MaximumDistance).Select(x=>{var zone=NativeZoneAdapter.GetZone(x.DistanceKm);if(zone is Result<int,DomainError>.Err e)throw new InvalidOperationException(e.Error.ToString());return new DeliveryReportRow(x.Id,x.DistanceKm,score(x.DistanceKm),((Result<int,DomainError>.Ok)zone).Value);}).OrderByDescending(x=>x.Cost).ThenBy(x=>x.Id,StringComparer.Ordinal).ToArray();}
 public static CategoryTotal[] ZoneReport(IEnumerable<ValidatedDeliveryRequest> items,Func<decimal,decimal> score){return items.WithinServiceRange(MaximumDistance).Select(x=>{var zone=NativeZoneAdapter.GetZone(x.DistanceKm);if(zone is Result<int,DomainError>.Err e)throw new InvalidOperationException(e.Error.ToString());return new{Zone=((Result<int,DomainError>.Ok)zone).Value,Cost=score(x.DistanceKm)};}).GroupBy(x=>x.Zone).Select(g=>new CategoryTotal(g.Key,g.Count(),g.Sum(x=>x.Cost))).OrderBy(x=>x.Zone).ToArray();}
}
public static class PricingPolicies{public static decimal Standard(decimal km)=>500m+100m*km;public static decimal Express(decimal km)=>800m+150m*km;}
public static class CurriedPricing
{
    public static Func<decimal, Func<decimal, Func<decimal, decimal>>> CreateScore
        => baseFee => rate => km => baseFee + rate * km;
}
public static class DeliveryFileBoundary{
 public static Result<ImmutableArray<ValidatedDeliveryRequest>,DomainError> Load(string path){try{using var reader=new StreamReader(path);var json=reader.ReadToEnd();return InputParser.Parse(json);}catch(FileNotFoundException){return new Result<ImmutableArray<ValidatedDeliveryRequest>,DomainError>.Err(new("FILE_NOT_FOUND",$"File not found: {path}"));}catch(DirectoryNotFoundException){return new Result<ImmutableArray<ValidatedDeliveryRequest>,DomainError>.Err(new("DIRECTORY_NOT_FOUND",$"Directory not found: {path}"));}catch(UnauthorizedAccessException ex){return new Result<ImmutableArray<ValidatedDeliveryRequest>,DomainError>.Err(new("FILE_ACCESS_DENIED",ex.Message));}catch(IOException ex){return new Result<ImmutableArray<ValidatedDeliveryRequest>,DomainError>.Err(new("FILE_READ_ERROR",ex.Message));}catch(System.Text.Json.JsonException ex){return new Result<ImmutableArray<ValidatedDeliveryRequest>,DomainError>.Err(new("MALFORMED_JSON",ex.Message));}}
}
